import{_ as n,C as l,o as e,c as p,j as i,E as t,a as s,a3 as r}from"./chunks/framework.C6R8kWFE.js";const j=JSON.parse(`{"title":"17-dars (Mentor). O'yin interfeysini prototiplash (1-qism): Wireframe, Mockup va Prototype bosqichlari","description":"","frontmatter":{"title":"17-dars (Mentor). O'yin interfeysini prototiplash (1-qism): Wireframe, Mockup va Prototype bosqichlari","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"9-sinf (Game)","link":"/mentor/9-sinf-game/"},"week":{"n":6,"link":"/mentor/9-sinf-game/hafta-06/"},"g":17,"title":"O'yin interfeysini prototiplash (1-qism): Wireframe, Mockup va Prototype bosqichlari","lead":"Chiroyli interfeys chizishdan oldin, uni qog'ozda sinab ko'rish arzon va tez. Bugun prototiplashning uch bosqichini va birinchi wireframe'ni o'rganamiz.","slide":"/slaydlar/9-sinf-game/hafta-06/dars-2.html","test":"/slaydlar/9-sinf-game/hafta-06/dars-2-test.html","student_link":"/9-sinf-game/hafta-06/dars-2","tabs":[{"g":16,"link":"/mentor/9-sinf-game/hafta-06/dars-1","current":false},{"g":17,"link":"/mentor/9-sinf-game/hafta-06/dars-2","current":true},{"g":18,"link":"/mentor/9-sinf-game/hafta-06/dars-3","current":false}],"prev":{"g":16,"title":"UI dizayn: tugmalar, menyular, HUD (3-qism): Jonli o'yin HUD'i (Health bar, tangalar, mini-xarita)","link":"/mentor/9-sinf-game/hafta-06/dars-1"},"next":{"g":18,"title":"O'yin interfeysini prototiplash (2-qism): O'yin stsenariysiga mos interfeys sxemasini chizish","link":"/mentor/9-sinf-game/hafta-06/dars-3"}}},"headers":[],"relativePath":"mentor/9-sinf-game/hafta-06/dars-2.md","filePath":"mentor/9-sinf-game/hafta-06/dars-2.md"}`),h={name:"mentor/9-sinf-game/hafta-06/dars-2.md"},m={class:"blk"},d={id:"dars-rejasi",tabindex:"-1"},g={class:"blk"},u={id:"mentor-konspekti",tabindex:"-1"},k={class:"blk"},y={id:"amaliy-topshiriqlar-va-yechimlar",tabindex:"-1"},q={class:"blk"},c={id:"tezkor-nazorat-savollari",tabindex:"-1"},v={class:"blk"},b={id:"uyga-vazifa",tabindex:"-1"};function f(z,a,P,_,x,T){const o=l("Icon");return e(),p("div",null,[i("div",m,[i("h2",d,[t(o,{name:"file-text"}),a[0]||(a[0]=s(" Dars rejasi ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#dars-rejasi","aria-label":'Permalink to "<Icon name="file-text" /> Dars rejasi"'},"​",-1))]),a[2]||(a[2]=r("<ul><li><strong>Darsning maqsadi:</strong> O&#39;quvchilarga prototiplash tushunchasi va uning o&#39;yin yaratishdagi ahamiyatini, qisqacha tarixini, prototip turlarini, Wireframe, Mockup va Prototype bosqichlari va ularning farqini, prototiplash vositalarini tanishtirish hamda qog&#39;ozda bosh menyu wireframe&#39;ini chizdirish.</li><li><strong>Kutiladigan natija:</strong> O&#39;quvchilar prototiplash nima va nima uchun kerakligini tushuntiradi; wireframe, Mockup va Prototype farqini aytadi; prototip turlaridan 4 tasini va 3 ta vositani sanaydi; prototip va vertikal kesim (vertical slice) farqini biladi; qog&#39;ozda bosh menyu wireframe&#39;ini chizadi.</li><li><strong>Vaqt taqsimoti:</strong><ul><li>16-dars: HUD maketi: 10 daqiqa</li><li>Prototiplash: nima, nega, tarixi: 10 daqiqa</li><li>Wireframe, Mockup, Prototype: 20 daqiqa</li><li>Turlar va vositalar: 15 daqiqa</li><li>Amaliyot: qog&#39;ozda wireframe: 25 daqiqa</li></ul></li></ul><blockquote><p>Manba: o&#39;quv dasturi — «O&#39;yin interfeysini prototiplash» moduli («prototiplash tushunchasi, uning o&#39;yin yaratishda ahamiyati; prototiplash turlari (Wireframe, Mockup, Prototype) va ularning vazifalari; qisqa tarixi; o&#39;yin dvijoklarida prototiplash; texnologiyalar: qog&#39;ozda chizish, grafik dasturlarda yaratish, dvijoklarda sinash»); o&#39;quv qo&#39;llanma — 2.5-bo&#39;lim (prototip vazifalari, turlari, prototip va vertikal kesim farqi, vositalar: Unity, GameMaker, Godot, Construct 3; Figma, Adobe XD, Axure RP; Photoshop&#39;da UI yaratish bosqichlari). Wireframe — Mockup — Prototype ta&#39;riflari umumiy UX amaliyotiga mos soddalashtirilgan.</p></blockquote><hr>",3))]),i("div",g,[i("h2",u,[t(o,{name:"file-text"}),a[3]||(a[3]=s(" Mentor konspekti ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#mentor-konspekti","aria-label":'Permalink to "<Icon name="file-text" /> Mentor konspekti"'},"​",-1))]),a[5]||(a[5]=r(`<h3 id="_1-prototiplash-tushunchasi-va-ahamiyati" tabindex="-1">1. Prototiplash tushunchasi va ahamiyati <a class="header-anchor" href="#_1-prototiplash-tushunchasi-va-ahamiyati" aria-label="Permalink to &quot;1. Prototiplash tushunchasi va ahamiyati&quot;">​</a></h3><p><strong>Prototiplash</strong> (prototyping) — dizayn g&#39;oyasini vizuallashtirish, uni to&#39;liq ishlab chiqishdan <strong>oldin</strong> tekshirish, o&#39;zaro ta&#39;sirni sinash va foydalanuvchilardan fikr olish jarayoni. Qo&#39;llanmaga ko&#39;ra prototip bir vaqtda bir nechta vazifani bajaradi: dastlabki g&#39;oyani tasdiqlaydi; taxmin qilingan mexanika va geympleyni sinaydi; boshqalarga ko&#39;rsatish uchun birinchi kontent bo&#39;ladi; keyingi vertikal kesim uchun asos yaratadi. Eng muhim foyda — <strong>xatoni erta va arzon topish</strong>: qog&#39;ozdagi chiziqni o&#39;chirish bir daqiqa, tayyor dasturni qayta yozish esa hafta oladi. Qisqa tarix (qo&#39;llanma): prototiplash sanoat dizayni va arxitekturada maketlar bilan boshlangan; dasturiy ta&#39;minotda 1970-yillarda mustaqil usul bo&#39;lib shakllandi; 1990-yillarda GUI tarqalishi bilan jarayonning ajralmas qismiga aylandi; 2002-yilda Axure RP kabi vositalar paydo bo&#39;ldi; hozir Figma, Sketch, Adobe XD kabi vositalar bor.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span>Prototip nima beradi:</span></span>
<span class="line"><span>1. G&#39;oyani tasdiqlaydi</span></span>
<span class="line"><span>2. Mexanika va geympleyni sinaydi</span></span>
<span class="line"><span>3. Boshqalarga ko&#39;rsatishga tayyor birinchi kontent</span></span>
<span class="line"><span>4. Vertikal kesim uchun asos</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Vaqt:  qog&#39;oz - daqiqalar</span></span>
<span class="line"><span>       raqamli maket - soatlar</span></span>
<span class="line"><span>       kod - kunlar, haftalar</span></span></code></pre></div><blockquote><p>Professional maslahat: Vaqt qiyoslari taxminiy, fikrni tushuntirish uchun. Qoida: muammo qanchalik erta topilsa, tuzatish shunchalik arzon.</p></blockquote><h3 id="_2-wireframe-mockup-va-prototype" tabindex="-1">2. Wireframe, Mockup va Prototype <a class="header-anchor" href="#_2-wireframe-mockup-va-prototype" aria-label="Permalink to &quot;2. Wireframe, Mockup va Prototype&quot;">​</a></h3><p>Interfeys uch bosqichda «aniqlashib» boradi. <strong>Wireframe</strong> (simli maket) — eng sodda sxema: qora-oq (yoki kulrang) to&#39;rtburchaklar, chiziqlar va yorliqlar; <strong>tuzilma va joylashuv</strong> (qaysi element qayerda) ko&#39;rsatiladi, rang, rasm va chiroyga e&#39;tibor berilmaydi. <strong>Mockup</strong> (maket) — wireframe ustiga <strong>vizual dizayn</strong>: ranglar, shriftlar, ikonkalar, soyalar; ko&#39;rinishi tayyor mahsulotga o&#39;xshaydi, lekin <strong>statik</strong> (tugma bosilmaydi). <strong>Prototype</strong> — <strong>interaktiv</strong> model: tugma bosilsa keyingi ekran ochiladi, o&#39;tishlar ishlaydi; foydalanish qulayligini sinash mumkin. Tartib: Wireframe → Mockup → Prototype. Har bosqichda savol boshqacha: wireframe&#39;da «hamma narsa o&#39;z o&#39;rnidami?», mockup&#39;da «chiroyli va tushunarlimi?», prototype&#39;da «ishlatish qulaymi?». Prototip <strong>vertikal kesim</strong> (vertical slice) emas: prototip asosiy mexanikaga e&#39;tibor qaratadi, vertikal kesim esa tayyor mahsulotning mini-versiyasi (grafika, ovoz, o&#39;yin jarayoni — hammasi sifatli).</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span>+------------------------------+</span></span>
<span class="line"><span>|           [LOGO]             |</span></span>
<span class="line"><span>|                              |</span></span>
<span class="line"><span>|        [ START ]             |</span></span>
<span class="line"><span>|        [ SOZLAMALAR ]        |</span></span>
<span class="line"><span>|        [ CHIQISH ]           |</span></span>
<span class="line"><span>|                              |</span></span>
<span class="line"><span>|  [?]                  [v1.0] |</span></span>
<span class="line"><span>+------------------------------+</span></span></code></pre></div><blockquote><p>Professional maslahat: Wireframe&#39;da faqat qutilar va yozuvlar. Rang, soya, ikonka — keyingi bosqich (Mockup) ishi.</p></blockquote><h3 id="_3-prototip-turlari-va-vositalari" tabindex="-1">3. Prototip turlari va vositalari <a class="header-anchor" href="#_3-prototip-turlari-va-vositalari" aria-label="Permalink to &quot;3. Prototip turlari va vositalari&quot;">​</a></h3><p>Qo&#39;llanma prototip turlarini sanaydi: <strong>qog&#39;oz prototiplari</strong>; raqamli <strong>statik</strong> prototiplar; <strong>bosiladigan</strong> (clickable) prototiplar; <strong>yuqori aniqlikdagi interaktiv</strong> prototiplar; <strong>kodlangan</strong> prototiplar; konseptual va xizmat prototiplari. O&#39;yin interfeysi uchun odatda: qog&#39;ozda chizish → grafik dasturda (Photoshop) maket → o&#39;yin dvigatelida sinash. <strong>Qog&#39;ozda prototiplash</strong> dasturlash ko&#39;nikmasini talab qilmaydi, o&#39;zgartirish oson; kamchiligi — ba&#39;zi interaktiv jihatlarni ko&#39;rsatish qiyin. <strong>Vositalar</strong> (qo&#39;llanma): dvigatellar — Unity, GameMaker, Unreal Engine, Godot, Construct 3, Defold; UI/UX vositalar — Figma, Adobe XD, Axure RP; maxsus — Machinations, Twine; grafik — Photoshop, Illustrator. Tanlov o&#39;yin turi va murakkabligiga bog&#39;liq. Photoshop&#39;da UI yaratishning prototiplash bosqichi — «past darajada detallashtirilgan maketlarni yaratish» (qo&#39;llanma): shundan keyingina vizual dizayn boshlanadi.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span>Qog&#39;oz va qalam   -&gt; eng birinchi g&#39;oya, 5 daqiqada</span></span>
<span class="line"><span>Photoshop / Figma -&gt; wireframe va mockup maketi</span></span>
<span class="line"><span>Unity / Godot     -&gt; interaktiv, o&#39;yin ichida sinash</span></span>
<span class="line"><span>Machinations      -&gt; o&#39;yin iqtisodi va mexanikasi</span></span>
<span class="line"><span>Twine             -&gt; hikoya (shoxlanuvchi) prototipi</span></span></code></pre></div><blockquote><p>Professional maslahat: Mukammal vosita yo&#39;q: avval eng oddiyini tanlang. Eng yaxshi prototip — g&#39;oyani eng tez tekshiradigani.</p></blockquote><hr>`,13))]),i("div",k,[i("h2",y,[t(o,{name:"file-text"}),a[6]||(a[6]=s(" Amaliy topshiriqlar va yechimlar ",-1)),a[7]||(a[7]=i("a",{class:"header-anchor",href:"#amaliy-topshiriqlar-va-yechimlar","aria-label":'Permalink to "<Icon name="file-text" /> Amaliy topshiriqlar va yechimlar"'},"​",-1))]),a[8]||(a[8]=r('<h3 id="_1-topshiriq-atamalar-oson" tabindex="-1">1-topshiriq. Atamalar (oson) <a class="header-anchor" href="#_1-topshiriq-atamalar-oson" aria-label="Permalink to &quot;1-topshiriq. Atamalar (oson)&quot;">​</a></h3><p>Wireframe, Mockup va Prototype ni bir gapda ta&#39;riflang.</p><p><strong>Bajarish tartibi:</strong> Wireframe — tuzilma va joylashuv sxemasi; Mockup — rang va shriftli statik vizual maket; Prototype — bosilib, ekranlar almashadigan interaktiv model.</p><h3 id="_2-topshiriq-bosqichni-toping-oson" tabindex="-1">2-topshiriq. Bosqichni toping (oson) <a class="header-anchor" href="#_2-topshiriq-bosqichni-toping-oson" aria-label="Permalink to &quot;2-topshiriq. Bosqichni toping (oson)&quot;">​</a></h3><p>«Menyu tugmalari qora-oq to&#39;rtburchaklar» — bu qaysi bosqich?</p><p><strong>Bajarish tartibi:</strong> Wireframe — faqat tuzilma va joylashuv, rang va bezak yo&#39;q.</p><h3 id="_3-topshiriq-vositalar-o-rta" tabindex="-1">3-topshiriq. Vositalar (o&#39;rta) <a class="header-anchor" href="#_3-topshiriq-vositalar-o-rta" aria-label="Permalink to &quot;3-topshiriq. Vositalar (o&#39;rta)&quot;">​</a></h3><p>O&#39;yin interfeysi prototipi uchun 3 ta vosita nomini va ularning vazifasini yozing.</p><p><strong>Bajarish tartibi:</strong> Photoshop/Figma — wireframe va mockup maketi; Unity yoki Godot — interaktiv sinov o&#39;yin ichida; qog&#39;oz va qalam — eng birinchi g&#39;oya.</p><h3 id="_4-topshiriq-prototip-va-vertikal-kesim-o-rta" tabindex="-1">4-topshiriq. Prototip va vertikal kesim (o&#39;rta) <a class="header-anchor" href="#_4-topshiriq-prototip-va-vertikal-kesim-o-rta" aria-label="Permalink to &quot;4-topshiriq. Prototip va vertikal kesim (o&#39;rta)&quot;">​</a></h3><p>Prototip va vertikal kesim farqini tushuntiring.</p><p><strong>Bajarish tartibi:</strong> Prototip asosiy mexanika va g&#39;oyani tez tekshiradi, tayyor bo&#39;lishi shart emas; vertikal kesim — tayyor mahsulotning mini-versiyasi bo&#39;lib, grafika, ovoz va o&#39;yin jarayoni sifatli.</p><h3 id="_5-topshiriq-qog-ozdagi-wireframe-qiyin" tabindex="-1">5-topshiriq. Qog&#39;ozdagi wireframe (qiyin) <a class="header-anchor" href="#_5-topshiriq-qog-ozdagi-wireframe-qiyin" aria-label="Permalink to &quot;5-topshiriq. Qog&#39;ozdagi wireframe (qiyin)&quot;">​</a></h3><p>Bosh menyu wireframe&#39;ini qog&#39;ozda chizing: logotip, START, Sozlamalar, Chiqish; hamkasbingiz bilan test qiling.</p><p><strong>Bajarish tartibi:</strong> 16:9 to&#39;rtburchak; yuqori o&#39;rtada logotip qutisi; markazda uchta tugma qutisi (START, SOZLAMALAR, CHIQISH); pastda versiya yorlig&#39;i. Hamkasb 5 soniyada START&#39;ni topsa — joylashuv yaxshi.</p><h3 id="_6-topshiriq-photoshop-ga-ko-chirish-bonus" tabindex="-1">6-topshiriq. Photoshop&#39;ga ko&#39;chirish (bonus) <a class="header-anchor" href="#_6-topshiriq-photoshop-ga-ko-chirish-bonus" aria-label="Permalink to &quot;6-topshiriq. Photoshop&#39;ga ko&#39;chirish (bonus)&quot;">​</a></h3><p>Wireframe&#39;ni Photoshop&#39;da 1920×1080 px kulrang qutilar bilan qayta chizing.</p><p><strong>Bajarish tartibi:</strong> File → New, 1920×1080 px; Rectangle Tool bilan kulrang qutilar; Text Tool bilan yorliqlar; har element alohida qatlam; Ctrl + G bilan «Bosh menyu» guruhi; PNG sifatida eksport.</p><hr>',19))]),i("div",q,[i("h2",c,[t(o,{name:"file-text"}),a[9]||(a[9]=s(" Tezkor nazorat savollari ",-1)),a[10]||(a[10]=i("a",{class:"header-anchor",href:"#tezkor-nazorat-savollari","aria-label":'Permalink to "<Icon name="file-text" /> Tezkor nazorat savollari"'},"​",-1))]),a[11]||(a[11]=r("<ol><li>Prototiplash nima? <ul><li><em>Javob:</em> Dizayn g&#39;oyasini ishlab chiqishdan oldin vizuallashtirib sinash jarayoni.</li></ul></li><li>Uch bosqichni ayting. <ul><li><em>Javob:</em> Wireframe, Mockup, Prototype.</li></ul></li><li>Wireframe da rang bo&#39;ladimi? <ul><li><em>Javob:</em> Yo&#39;q, faqat tuzilma va joylashuv.</li></ul></li><li>Prototip turlaridan 3 tasi? <ul><li><em>Javob:</em> Qog&#39;oz, statik raqamli, bosiladigan, yuqori aniqlikdagi interaktiv.</li></ul></li><li>Prototip va vertikal kesim farqi? <ul><li><em>Javob:</em> Prototip mexanikani tekshiradi; vertikal kesim tayyor mahsulotning mini-versiyasi.</li></ul></li></ol><hr>",2))]),i("div",v,[i("h2",b,[t(o,{name:"house"}),a[12]||(a[12]=s(" Uyga vazifa ",-1)),a[13]||(a[13]=i("a",{class:"header-anchor",href:"#uyga-vazifa","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa"'},"​",-1))]),a[14]||(a[14]=i("ol",null,[i("li",null,"Bosh menyu wireframe'ini qog'ozda chizing (logotip, START, Sozlamalar, Chiqish) va suratga oling."),i("li",null,"O'yin ekrani wireframe'ini chizing: HUD elementlarining joylari 16-darsdagi kabi bo'lsin."),i("li",null,"Wireframe, Mockup va Prototype farqini 3 ta jumlada yozing."),i("li",null,"Oilangiz a'zosi yoki do'stingizga wireframe'ni ko'rsating: «START tugmasi qayerda?» deb so'rang va natijani yozing.")],-1))])])}const M=n(h,[["render",f]]);export{j as __pageData,M as default};
